package Notify;
use strict;
use warnings;

# Send a plain-text notice with the system mailer; $run executes a command.
sub send_notice {
    my ($run, $recipient, $subject) = @_;
    return $run->("mail -s '$subject' $recipient < notice.txt");
}

1;

use strict;
use warnings;
use Test::More;
use Notify;

subtest returns_runner_status => sub {
    is(Notify::send_notice(sub { 0 }, 'ann@example.test', 'Hi'), 0, 'status');
};

done_testing;
